jsonTools.init:
function init(eli) {
  // Harvey Helper (ELI for Harvey): what to run in Harvey for this document, ready-to-paste prompts,
  // a before-Harvey checklist, after-Harvey clean-up and links. No Harvey connection; reads the document only.
  eli = eli || window.eli;
  if (!eli) return;

  var HARVEY_URL = "https://app.harvey.ai";
  var AGENTS = {
    ask: "EI - Ask Harvey (All)", redlines: "EI - Review Redlines (All)", compare: "EI - Compare Document (All)",
    sow: "EI - Draft SOW (All)", renewal: "EI - Draft Renewal (All)", termination: "EI - Draft Termination (All)",
  };

  function esc(s) {
    return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;")
      .replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function toast(m, k) { if (typeof showToast === "function") showToast(m, k || "info"); }
  function copy(text, label) {
    if (eli.ui && typeof eli.ui.copyText === "function") return Promise.resolve(eli.ui.copyText(text, label));
    try { return navigator.clipboard.writeText(text).then(function () { toast("Copied", "ok"); }); }
    catch (e) { return Promise.resolve(); }
  }
  function openLink(url) {
    try { if (window.Office && Office.context && Office.context.ui && Office.context.ui.openBrowserWindow) { Office.context.ui.openBrowserWindow(url); return; } } catch (e) { }
    copy(url, "Link");
  }

  // ── facts about this document ──────────────────────────────────────
  function oarsFacts() {
    var st = null;
    try { var f = eli.get && eli.get("oars", "getState"); st = f ? f() : null; } catch (e) { }
    var t = (st && st.text) || "";
    function field(label) { var m = new RegExp(label + "[^:\\n]*:\\s*([^\\n]+)", "i").exec(t); return m ? m[1].trim().slice(0, 80) : ""; }
    return {
      loaded: !!st,
      type: field("Agreement Type") || field("Type of Agreement"),
      party: field("Third Party Name") || field("Counterparty"),
      ref: field("Agreement Request Number") || field("CP Ref"),
    };
  }
  function readDoc() {
    var typeP = (eli.host && typeof eli.host.detectAgreementType === "function")
      ? Promise.resolve(eli.host.detectAgreementType({ detail: true })).catch(function () { return null; }) : Promise.resolve(null);
    var tcP = (eli.host && typeof eli.host.runRaw === "function")
      ? Promise.resolve(eli.host.runRaw("harvey_helper:tracked_changes", function (context) {
        var tcs = context.document.body.getTrackedChanges();
        tcs.load("items/author,items/type");
        return context.sync().then(function () {
          var by = {};
          tcs.items.forEach(function (c) { var a = c.author || "Unknown"; by[a] = (by[a] || 0) + 1; });
          return { total: tcs.items.length, byAuthor: by };
        });
      })).catch(function () { return null; }) : Promise.resolve(null);
    return Promise.all([typeP, tcP]).then(function (r) {
      var det = r[0], type = "", title = "";
      if (det && typeof det === "object") { type = det.type || ""; title = det.title || ""; } else if (typeof det === "string") type = det;
      return { type: type, title: title, tc: r[1] };
    });
  }
  function classify(authors) {
    var r; try { r = eli.dispatch("authors", "classify", authors); } catch (e) { r = undefined; }
    return Promise.resolve(r).then(function (m) { return (m && typeof m === "object") ? m : {}; }).catch(function () { return {}; });
  }

  // ── what to run ────────────────────────────────────────────────────
  function recommend(doc, of, classes) {
    var recs = [], kind = (doc.type + " " + doc.title + " " + of.type).toLowerCase();
    var tc = doc.tc || { total: 0, byAuthor: {} };
    var ext = 0, harvey = 0;
    Object.keys(tc.byAuthor).forEach(function (a) {
      if (/harvey/i.test(a)) harvey += tc.byAuthor[a];
      else if (classes[a] === "external") ext += tc.byAuthor[a];
    });
    if (ext > 0) recs.push({ agent: AGENTS.redlines, why: ext + " tracked change" + (ext === 1 ? "" : "s") + " from the other side" });
    if (/statement of work|\bsow\b/.test(kind)) recs.push({ agent: AGENTS.sow, why: "This is a Statement of Work" });
    else if (/renewal|extension/.test(kind)) recs.push({ agent: AGENTS.renewal, why: "This is a renewal" });
    else if (/termination/.test(kind)) recs.push({ agent: AGENTS.termination, why: "This is a termination" });
    if (!ext && tc.total === 0 && !of.loaded) recs.push({ agent: AGENTS.compare, why: "Third-party paper? Compare it with our standard template" });
    recs.push({ agent: AGENTS.ask, why: "Any question about this agreement" });
    return { recs: recs, harvey: harvey, ext: ext, total: tc.total };
  }
  function prompts(doc, of) {
    var type = of.type || doc.type || "agreement", party = of.party ? " with " + of.party : "", ref = of.ref ? " (CP Ref " + of.ref + ")" : "";
    var what = "this " + type + party + ref;
    return [
      { label: "Review the other side's redlines", text: "Review the other side's redlines in " + what + " using the matching EI playbook. Accept, reject or amend each change, and give the reason." },
      { label: "Compare with our template", text: "Compare " + what + " with our standard EI template and list every material difference, with the clause and section number." },
      { label: "Summarise key terms", text: "Summarise the key terms of " + what + ": parties, term and expiry, fees, IP ownership, confidentiality, liability cap and termination. Quote the section number for each." },
      { label: "Find a clause", text: "In " + what + ", find the clause on [topic]. Quote it with its section number and explain it in plain English." },
    ];
  }

  // ── panel ──────────────────────────────────────────────────────────
  function show(opts) {
    var focus = (opts && typeof opts === "object" && opts.focus) ? String(opts.focus) : "";
    var out = (eli.ui && eli.ui.claimOutput) ? eli.ui.claimOutput() : document.getElementById("output");
    if (!out) return;
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedHarveyHelper"); } catch (e) { }
    out.innerHTML = '<div class="_hh_root"><div class="_hh_head"><button class="_hh_back" id="_hh_back">←</button>' +
      '<div><div class="_hh_eye">ELI FOR HARVEY</div><div class="_hh_title">Harvey Helper</div></div></div>' +
      '<div id="_hh_body"><div class="_hh_note">Reading this document…</div></div></div>';
    out.querySelector("#_hh_back").onclick = function () { if (typeof showHome === "function") showHome(); };
    var of = oarsFacts();
    readDoc().then(function (doc) {
      var authors = doc.tc ? Object.keys(doc.tc.byAuthor) : [];
      return classify(authors).then(function (cls) { paint(out, doc, of, cls, focus); });
    }).catch(function () { paint(out, { type: "", title: "", tc: null }, of, {}, focus); });
  }

  function paint(out, doc, of, cls, focus) {
    var r = recommend(doc, of, cls), ps = prompts(doc, of);
    if (focus && !r.recs.some(function (x) { return x.agent === focus; })) r.recs.unshift({ agent: focus, why: "Suggested on the home page" });
    var facts = [of.type || doc.type, of.party, of.ref ? "CP Ref " + of.ref : ""].filter(Boolean).join(" · ") || (doc.title || "This document");
    var h = '<div class="_hh_doc">📄 ' + esc(facts) + (r.total ? ' · ' + r.total + ' tracked change' + (r.total === 1 ? '' : 's') : '') + '</div>';

    h += '<div class="_hh_sec">WHAT TO RUN IN HARVEY</div>' + r.recs.map(function (x, i) {
      return '<div class="_hh_rec' + (focus ? (x.agent === focus ? ' _hh_top _hh_focus' : '') : (i === 0 ? ' _hh_top' : '')) + '"><div><div class="_hh_agent">' + esc(x.agent) + '</div><div class="_hh_why">' + esc(x.why) + '</div></div>' +
        '<button class="_hh_btn" data-copy="' + esc(x.agent) + '" data-label="Agent name">COPY NAME</button></div>';
    }).join("") + '<div class="_hh_tip">In Harvey for Word: Agents tab, or type @ and paste the name.</div>';

    h += '<div class="_hh_sec">READY-TO-PASTE PROMPTS</div>' + ps.map(function (p) {
      return '<div class="_hh_prompt"><div class="_hh_pl">' + esc(p.label) + '</div><div class="_hh_pt">' + esc(p.text) + '</div>' +
        '<button class="_hh_btn" data-copy="' + esc(p.text) + '" data-label="Prompt">COPY</button></div>';
    }).join("");

    h += '<div class="_hh_sec">BEFORE YOU RUN HARVEY</div><ul class="_hh_list">' +
      '<li>Pick a <b>frontier model</b> in the model selector. Auto uses an older, less accurate model.</li>' +
      '<li>Give it <b>only the documents it needs</b>.</li>' +
      '<li>To find past agreements, use the <b>EI - OARS Data</b> Vault (Final Executed) first, then <b>EI - Tech Agreements Full</b>.</li>' +
      '<li>Ask it to <b>quote the section number</b> behind every answer, and check it.</li></ul>';

    h += '<div class="_hh_sec">AFTER HARVEY</div>';
    h += r.harvey ? '<div class="_hh_after">Harvey has <b>' + r.harvey + '</b> tracked change' + (r.harvey === 1 ? '' : 's') + ' in this document not yet accepted or rejected. Review them before sending.</div>'
      : '<div class="_hh_after">No unreviewed changes from Harvey in this document.</div>';
    h += '<div class="_hh_row"><button class="_hh_btn _hh_wide" data-tile="app_docuscrub" data-tool="docuscrub">🧼 RUN DOCUSCRUB</button>' +
      '<button class="_hh_btn _hh_wide" data-tile="app_format_check" data-tool="format_check">📐 FORMAT CHECK</button></div>';

    h += '<div class="_hh_sec">LINKS</div><div class="_hh_row"><button class="_hh_btn _hh_wide" data-url="' + HARVEY_URL + '">🌐 OPEN HARVEY</button></div>';

    var body = out.querySelector("#_hh_body"); if (!body) return;
    body.innerHTML = h;
    Array.prototype.forEach.call(body.querySelectorAll("[data-copy]"), function (b) {
      b.onclick = function () { copy(b.getAttribute("data-copy"), b.getAttribute("data-label")); };
    });
    Array.prototype.forEach.call(body.querySelectorAll("[data-tile]"), function (b) {
      b.onclick = function () {
        var cat = b.getAttribute("data-tile"), toolId = b.getAttribute("data-tool");
        var has = function () { return !!(eli.get && typeof eli.get("tile", cat) === "function"); };
        var go = function () { try { eli.dispatch("tile", cat); } catch (e) { } };
        if (has()) { go(); return; }
        var ready = (eli.tools && typeof eli.tools.ensureLoaded === "function") ? eli.tools.ensureLoaded(toolId) : null;
        Promise.resolve(ready).catch(function () { }).then(function () {
          if (has()) go(); else toast("That tool isn't installed. Open Data Hub to install it.", "warn");
        });
      };
    });
    Array.prototype.forEach.call(body.querySelectorAll("[data-url]"), function (b) { b.onclick = function () { openLink(b.getAttribute("data-url")); }; });
    var f = body.querySelector("._hh_focus"); if (f && f.scrollIntoView) f.scrollIntoView({ block: "center" });
  }

  eli.register({ tile: { app_harvey_helper: function () { show(); } }, harvey_helper: { open: show } });
}

jsonTools.css:
._hh_root { background: linear-gradient(180deg, #0d1b2a 0%, #1b263b 100%); min-height: 100%; padding: 0 0 16px; font-family: 'Inter', sans-serif; color: #f1f5f9; }
._hh_head { display: flex; align-items: center; gap: 12px; padding: 12px 14px; background: linear-gradient(180deg, #141f35, #0f1828); border-bottom: 2px solid #c9a227; }
._hh_back { background: transparent; border: none; color: #fff; font-size: 18px; cursor: pointer; padding: 0 4px; }
._hh_eye { color: #c9a227; font: 800 9px/1 'Inter', sans-serif; letter-spacing: 1.6px; }
._hh_title { font-family: 'Source Serif 4', Georgia, serif; font-weight: 700; font-size: 19px; color: #fff; margin-top: 2px; }
#_hh_body { padding: 12px 14px; }
._hh_note { color: #94a3b8; font-size: 12px; }
._hh_doc { border: 1px solid rgba(201,162,39,0.35); border-left: 3px solid #c9a227; background: rgba(255,255,255,0.04); padding: 8px 10px; font: 600 11.5px/1.4 'Inter', sans-serif; }
._hh_sec { color: #f2d866; font: 800 9.5px/1 'Inter', sans-serif; letter-spacing: 1.6px; margin: 16px 0 8px; padding-bottom: 5px; border-bottom: 1px solid rgba(201,162,39,0.35); }
._hh_rec, ._hh_prompt { display: flex; align-items: center; justify-content: space-between; gap: 10px; border: 1px solid rgba(201,162,39,0.3); background: radial-gradient(circle at 20% 20%, rgb(201 162 39 / 0.12) 0%, #0b0f19 70%); padding: 8px 10px; margin-bottom: 6px; }
._hh_top { border: 2px solid #c9a227; box-shadow: 0 0 12px rgba(201,162,39,0.3); }
._hh_agent { font: 800 12px/1.3 'Inter', sans-serif; color: #fff; }
._hh_why { font: 500 10.5px/1.3 'Inter', sans-serif; color: #94a3b8; margin-top: 2px; }
._hh_tip { color: #7d8aa5; font: 500 10.5px/1.4 'Inter', sans-serif; margin-top: 2px; }
._hh_prompt { align-items: flex-start; flex-wrap: wrap; }
._hh_pl { font: 800 11px/1.3 'Inter', sans-serif; color: #e5cc80; width: 100%; }
._hh_pt { font: 500 11px/1.45 'Inter', sans-serif; color: #cbd5e1; flex: 1; min-width: 0; }
._hh_btn { flex: none; border: 1px solid #c9a227; background: #101827; color: #f2d866; font: 800 9.5px/1 'Inter', sans-serif; letter-spacing: 1px; padding: 7px 10px; cursor: pointer; border-radius: 0; }
._hh_btn:hover { background: rgba(201,162,39,0.15); }
._hh_row { display: flex; gap: 8px; }
._hh_wide { flex: 1; padding: 10px; }
._hh_list { margin: 0; padding-left: 18px; font: 500 11.5px/1.55 'Inter', sans-serif; color: #dbe2ee; }
._hh_list b { color: #fff; }
._hh_after { font: 500 11.5px/1.45 'Inter', sans-serif; color: #dbe2ee; margin-bottom: 8px; }
._hh_after b { color: #f2d866; }
._hh_focus { animation: _hh_pulse 1.2s ease-out 2; }
@keyframes _hh_pulse { 0% { box-shadow: 0 0 0 0 rgba(242,216,102,0.7); } 100% { box-shadow: 0 0 0 10px rgba(242,216,102,0); } }
